/**
 *
 * Copies the page styles into the shadow roots PrimeVue components render in. Not needed with
 * isolated mode, which handles shadow roots itself.
 *
 * @module shadowroot
 * @experimental
 *
 */
import type { PrimeVueShadowRootOption } from '@primevue/core/config';

/**
 * Turns on copying styles into shadow roots.
 *
 * @returns The value for the `shadowRoot` option.
 *
 * @example
 * app.use(PrimeVue, { theme, shadowRoot: withShadowRoot() });
 *
 * @experimental
 */
export declare function withShadowRoot(): PrimeVueShadowRootOption;

/**
 * Copies the page styles into a shadow root.
 *
 * @param root The shadow root. Each call needs one `detachStyleRoot`.
 *
 * @experimental
 */
export declare function attachStyleRoot(root: ShadowRoot | null | undefined): void;

/**
 * Stops copying into a shadow root attached with `attachStyleRoot`.
 *
 * @param root The shadow root.
 *
 * @experimental
 */
export declare function detachStyleRoot(root: ShadowRoot | null | undefined): void;

/**
 * Removes a style's copies from every shadow root.
 *
 * @param name The style name.
 *
 * @experimental
 */
export declare function unmirrorStyle(name: string): void;
